- (NSButton *)makeButtonForItemImage:(NSImage *)image target:(id)target action:(SEL)action
{
	if (image == nil) {
		return nil;
	}
	NSButton *button = [NSButton buttonWithImage:image target:target action:action];
	// Bordered so the toolbar buttons pick up the macOS 26 Liquid Glass capsule.
	[button setBezelStyle:NSBezelStyleTexturedRounded];
	[button setBordered:YES];
	[button setTranslatesAutoresizingMaskIntoConstraints:NO];
	[button setSymbolConfiguration:[NSImageSymbolConfiguration configurationWithPointSize:15
																					  weight:NSFontWeightRegular
																					   scale:NSImageSymbolScaleMedium]];
	[button setImageScaling:NSImageScaleProportionallyDown];
	return button;
}

